# # `preprocessing` 데이터 전처리 모듈

# scikit-learn 의 preprocessing 모듈
# 데이터 전처리 는 많은 작업들을 하게 되는데,
# 대표적인게 scaling 입니다.
# 데이터의 feature scaling 이라고도 합니다.

# scaling 방법은 크게 두가지가 있습니다.
#  1. 표준화 (standardization)
#  2. 정규화 (normalization)

# 정규화와 표준화는 모두 머신러닝 알고리즘을 훈련시키는데 있어서
# 사용되는 특성(feature)들이 '모두 비슷한 영향력'을 행사하도록
# 값을 변환해주는 전처리 기술입니다

# ![](https://img1.daumcdn.net/thumb/R1280x0/?scode=mtistory2&fname=https%3A%2F%2Fblog.kakaocdn.net%2Fdn%2FxaTIu%2FbtqFzbvLruS%2FKwRY1VUfZIhSKNd6nV97K0%2Fimg.jpg)

# * 데이터의 특징 스케일링(feature scaling)을 위한 방법으로 표준화(Standardization)와 정규화(Normalization) 사용
# 
# + 표준화 방법
# 
# \begin{equation}
# x_i^{'} = \frac{x_i-mean(x)}{stdev(x)}
# \end{equation}
# 
# + 정규화 방법
# 
# \begin{equation}
# x_i^{'} = \frac{x_i-min(x)}{max(x)-min(x)}
# \end{equation}
# 
# + scikit-learn에서는 개별 벡터 크기를 맞추는 형태로 정규화

# ## `StandardScaler`: 표준화 클래스

from sklearn.datasets import load_iris

iris = load_iris()

iris_df = pd.DataFrame(data = iris.data, columns = iris.feature_names)
iris_df
# >>> 출력:
#      sepal length (cm)  sepal width (cm)  petal length (cm)  petal width (cm)
# 0                  5.1               3.5                1.4               0.2
# 1                  4.9               3.0                1.4               0.2
# 2                  4.7               3.2                1.3               0.2
# 3                  4.6               3.1                1.5               0.2
# 4                  5.0               3.6                1.4               0.2
# ..                 ...               ...                ...               ...
# 145                6.7               3.0                5.2               2.3
# 146                6.3               2.5                5.0               1.9
# 147                6.5               3.0                5.2               2.0
# 148                6.2               3.4                5.4               2.3
# 149                5.9               3.0                5.1               1.8
# 
# [150 rows x 4 columns]

iris_df.describe()
# >>> 출력:
#        sepal length (cm)  sepal width (cm)  petal length (cm)  \
# count         150.000000        150.000000         150.000000   
# mean            5.843333          3.057333           3.758000   
# std             0.828066          0.435866           1.765298   
# min             4.300000          2.000000           1.000000   
# 25%             5.100000          2.800000           1.600000   
# 50%             5.800000          3.000000           4.350000   
# 75%             6.400000          3.300000           5.100000   
# max             7.900000          4.400000           6.900000   
# 
#        petal width (cm)  
# count        150.000000  
# mean           1.199333  
# std            0.762238  
# min            0.100000  

from sklearn.preprocessing import StandardScaler

scaler = StandardScaler()

# 스케일링을 위해 몇가지 과정을 거쳐야 한다
# step 1 : 기본적으로 fit() 을 하여 scaling에 필요한 정보들을 가져옵니다.
# step 2 : 가져온 정보에 따라서 scaling 을 위한 transform() 메소드를 호출하여
#          scaling 된 변환을 거칩니다.

# 위 step1, step2 를 '동시에' 에 수행하는 fit_transform()

# 방법1: fit() + transform()
scaler.fit(iris_df)
iris_scaled = scaler.transform(iris_df)

# 방법2
iris_scaled = scaler.fit_transform(iris_df)

type(iris_scaled)
# >>> 출력:
# numpy.ndarray

iris_df_scaled = pd.DataFrame(data=iris_scaled, columns=iris.feature_names)
iris_df_scaled.describe()
# >>> 출력:
#        sepal length (cm)  sepal width (cm)  petal length (cm)  \
